-- =============================================================================
-- VERDICT — placeholder scenario seed
-- 200 scenarios across 12 categories. Source = 'curated'. Placeholders.
-- All real names anonymized. Side labels + meanings are scenario-specific.
-- Replace via scripts/import-scenarios.ts before public launch.
-- =============================================================================

begin;

insert into public.scenarios
  (text, question, context_tag, side_a_label, side_b_label, side_a_meaning, side_b_meaning, category, freshness_tier, source) values
